#requires -Version 5.1
<#
.SYNOPSIS
    RFPY installer for Windows.
.DESCRIPTION
    Installs the generic RFPY manager. Without -InstallDir, a native Windows dialog proposes C:\RFPY.
    RFPY manages isolated Python / Robot Framework environments, repositories,
    proxy settings, diagnostics and a local Web UI.
#>
[CmdletBinding(PositionalBinding=$false)]
param(
    [Alias('i')][string]$InstallDir = '',
    [Alias('u')][string]$UvVersion = '0.12.23',
    [Alias('tp')][string]$ToolPythonVersion = '3.13.16',
    [Alias('px')][string]$ProxyUrl = '',
    [Alias('uu')][string]$UvUrl = '',
    [Alias('np')][switch]$NoPath,
    [Alias('w')][switch]$LaunchWeb,
    [Alias('h','?')][switch]$Help,
    [Parameter(ValueFromRemainingArguments=$true)][object[]]$RemainingArgs
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$InstallerVersion = '1.0.0'
$InstallDirExplicit = $PSBoundParameters.ContainsKey('InstallDir') -and -not [string]::IsNullOrWhiteSpace($InstallDir)

trap {
    $m = [string]$_.Exception.Message
    if ([string]::IsNullOrWhiteSpace($m)) { $m = 'Erreur RFPY inattendue.' }
    Write-Host "`n[ERREUR] $m" -ForegroundColor Red
    exit 1
}

# PS2EXE / Windows PowerShell can pass --long-option as -long-option.
# Parse remaining arguments explicitly and normalize both forms.
$LongOptions = @{
    '--install-dir' = @{Name='InstallDir'; Switch=$false}
    '--uv-version' = @{Name='UvVersion'; Switch=$false}
    '--tool-python' = @{Name='ToolPythonVersion'; Switch=$false}
    '--tool-python-version' = @{Name='ToolPythonVersion'; Switch=$false}
    '--proxy-url' = @{Name='ProxyUrl'; Switch=$false}
    '--uv-url' = @{Name='UvUrl'; Switch=$false}
    '--no-path' = @{Name='NoPath'; Switch=$true}
    '--launch-web' = @{Name='LaunchWeb'; Switch=$true}
    '--help' = @{Name='Help'; Switch=$true}
}
$tokens = [System.Collections.Generic.List[object]]::new()
if ($InstallDir -match '^-[A-Za-z][A-Za-z0-9-]{2,}(?:=.*)?$') {
    $candidate = '--' + $InstallDir.Substring(1)
    $candidateName = (($candidate -split '=',2)[0]).ToLowerInvariant()
    if ($LongOptions.ContainsKey($candidateName)) {
        $tokens.Add($InstallDir)
        $InstallDir = ''
        $InstallDirExplicit = $false
    }
}
foreach ($a in @($RemainingArgs)) { $tokens.Add($a) }
for ($ix=0; $ix -lt $tokens.Count; $ix++) {
    $token = ([string]$tokens[$ix]).Trim()
    if ([string]::IsNullOrWhiteSpace($token)) { continue }
    if ($token -match '^-[A-Za-z][A-Za-z0-9-]{2,}(?:=.*)?$') {
        $candidate = '--' + $token.Substring(1)
        $candidateName = (($candidate -split '=',2)[0]).ToLowerInvariant()
        if ($LongOptions.ContainsKey($candidateName)) { $token = $candidate }
    }
    $inline = $null
    $name = $token
    if ($token -match '^(--[^=]+)=(.*)$') { $name=$Matches[1]; $inline=$Matches[2] }
    $key = $name.ToLowerInvariant()
    if (-not $LongOptions.ContainsKey($key)) { throw "Parametre inconnu : $token" }
    $spec = $LongOptions[$key]
    if ($spec.Switch) {
        Set-Variable -Name $spec.Name -Value $true -Scope Script
        continue
    }
    $value = $inline
    if ($null -eq $value) {
        $ix++
        if ($ix -ge $tokens.Count) { throw "Valeur manquante pour $name" }
        $value = [string]$tokens[$ix]
    }
    Set-Variable -Name $spec.Name -Value $value -Scope Script
    if ($spec.Name -eq 'InstallDir') { $InstallDirExplicit = $true }
}

function Show-Help {
    Write-Host "RFPY installer v$InstallerVersion" -ForegroundColor Cyan
    Write-Host ''
    Write-Host '  -i,  --install-dir <path>       Racine (si absent : dialogue, C:\RFPY proposé)'
    Write-Host '  -u,  --uv-version <version>     uv (defaut 0.12.23)'
    Write-Host '  -tp, --tool-python <version>    Python du manager RFPY (defaut 3.13.16)'
    Write-Host '  -px, --proxy-url <url>          Proxy initial optionnel'
    Write-Host '  -uu, --uv-url <url>             URL ZIP uv alternative'
    Write-Host '  -np, --no-path                  Ne modifie pas le PATH utilisateur'
    Write-Host '  -w,  --launch-web               Ouvre l UI Web apres installation'
    Write-Host '  -h,  --help                     Aide'
 }

function Select-RfpyInstallDirectory([string]$DefaultPath) {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing
    [System.Windows.Forms.Application]::EnableVisualStyles()

    $form = New-Object System.Windows.Forms.Form
    $form.Text = 'RFPY - Installation'
    $form.StartPosition = 'CenterScreen'
    $form.Size = New-Object System.Drawing.Size(650,205)
    $form.MinimumSize = New-Object System.Drawing.Size(650,205)
    $form.MaximizeBox = $false
    $form.MinimizeBox = $false
    $form.TopMost = $true

    $title = New-Object System.Windows.Forms.Label
    $title.Text = "Répertoire d'installation de RFPY"
    $title.AutoSize = $true
    $title.Font = New-Object System.Drawing.Font('Segoe UI',11,[System.Drawing.FontStyle]::Bold)
    $title.Location = New-Object System.Drawing.Point(18,18)
    $form.Controls.Add($title)

    $box = New-Object System.Windows.Forms.TextBox
    $box.Location = New-Object System.Drawing.Point(20,55)
    $box.Size = New-Object System.Drawing.Size(485,25)
    $box.Text = $DefaultPath
    $form.Controls.Add($box)

    $browse = New-Object System.Windows.Forms.Button
    $browse.Text = 'Parcourir...'
    $browse.Location = New-Object System.Drawing.Point(515,53)
    $browse.Size = New-Object System.Drawing.Size(105,29)
    $form.Controls.Add($browse)

    $cancel = New-Object System.Windows.Forms.Button
    $cancel.Text = 'Annuler'
    $cancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $cancel.Location = New-Object System.Drawing.Point(405,115)
    $cancel.Size = New-Object System.Drawing.Size(100,30)
    $form.Controls.Add($cancel)

    $install = New-Object System.Windows.Forms.Button
    $install.Text = 'Installer'
    $install.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $install.Location = New-Object System.Drawing.Point(515,115)
    $install.Size = New-Object System.Drawing.Size(105,30)
    $form.Controls.Add($install)
    $form.AcceptButton = $install
    $form.CancelButton = $cancel

    $browse.Add_Click({
        $picker = New-Object System.Windows.Forms.FolderBrowserDialog
        $picker.Description = 'Choisir le répertoire de base RFPY'
        $picker.ShowNewFolderButton = $true
        if (Test-Path -LiteralPath $box.Text -PathType Container) { $picker.SelectedPath = $box.Text }
        if ($picker.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) { $box.Text = $picker.SelectedPath }
        $form.Activate(); $form.BringToFront()
    })
    $form.Add_Shown({ $this.Activate(); $this.BringToFront(); $box.SelectAll(); $box.Focus() })

    $result = $form.ShowDialog()
    $chosen = $box.Text.Trim()
    $form.Dispose()
    if ($result -ne [System.Windows.Forms.DialogResult]::OK) { return $null }
    if ([string]::IsNullOrWhiteSpace($chosen)) { throw "Le répertoire d'installation ne peut pas être vide." }
    return $chosen
}

if ($Help) { Show-Help; exit 0 }
if (-not $InstallDirExplicit) {
    $InstallDir = Select-RfpyInstallDirectory -DefaultPath 'C:\RFPY'
    if ([string]::IsNullOrWhiteSpace($InstallDir)) { Write-Host '[RFPY] Installation annulée.'; exit 0 }
}
if ([string]::IsNullOrWhiteSpace($InstallDir)) { throw 'InstallDir est vide.' }
$InstallDir = [IO.Path]::GetFullPath($InstallDir)
$BinDir = Join-Path $InstallDir 'bin'
$AppDir = Join-Path $InstallDir 'app'
$ToolsDir = Join-Path $InstallDir 'tools'
$UvDir = Join-Path $ToolsDir 'uv'
$UvExe = Join-Path $UvDir 'uv.exe'
$RuntimeDir = Join-Path $InstallDir 'runtime\python'
$AppVenv = Join-Path $InstallDir '.appvenv'
$AppPython = Join-Path $AppVenv 'Scripts\python.exe'
$ConfigDir = Join-Path $InstallDir 'config'
$ConfigFile = Join-Path $ConfigDir 'rfpy.json'
$TempDir = Join-Path $InstallDir 'tmp'

function Ensure-Folder([string]$p) { if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null } }
function Write-Stage([string]$t) { Write-Host "`n==> $t" -ForegroundColor Cyan }
function Write-Success([string]$t) { Write-Host "[OK] $t" -ForegroundColor Green }

function Run-External {
    param([string]$FilePath,[string[]]$Arguments=@(),[switch]$Capture)
    $oldEap = $ErrorActionPreference
    $rc = -1
    $out = @()
    try {
        $ErrorActionPreference = 'Continue'
        if ($Capture) { $out = @(& $FilePath @Arguments 2>&1 | ForEach-Object { [string]$_ }) }
        else { & $FilePath @Arguments 2>&1 | ForEach-Object { Write-Host ([string]$_) } }
        $rc = $LASTEXITCODE
    } finally { $ErrorActionPreference = $oldEap }
    if ($null -eq $rc) { $rc = -1 }
    if ($rc -ne 0) { throw "Commande en echec ($rc): $FilePath $($Arguments -join ' ')" }
    return [pscustomobject]@{ ExitCode=$rc; Output=$out }
}

function Ensure-UserPath([string]$Entry) {
    $current = [Environment]::GetEnvironmentVariable('Path', 'User')
    $parts = @()
    if (-not [string]::IsNullOrWhiteSpace($current)) {
        $parts = @($current -split ';' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    }

    $filtered = @($parts | Where-Object { $_.TrimEnd('\\') -ine $Entry.TrimEnd('\\') })
    $newUserPath = ((@($Entry) + $filtered) -join ';')
    [Environment]::SetEnvironmentVariable('Path', $newUserPath, 'User')

    # Relire la valeur persistante : ne jamais annoncer OK sans verification.
    $stored = [Environment]::GetEnvironmentVariable('Path', 'User')
    $storedParts = @($stored -split ';' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if (-not ($storedParts | Where-Object { $_.TrimEnd('\\') -ieq $Entry.TrimEnd('\\') })) {
        throw "Impossible d enregistrer RFPY dans le PATH utilisateur : $Entry"
    }

    $proc = @($env:Path -split ';' | Where-Object {
        -not [string]::IsNullOrWhiteSpace($_) -and $_.TrimEnd('\\') -ine $Entry.TrimEnd('\\')
    })
    $env:Path = ((@($Entry) + $proc) -join ';')

    Write-Success "PATH utilisateur configure : $Entry"
}

function Signal-EnvironmentUpdate {
    # Best effort : signale aux applications Windows que l environnement utilisateur a change.
    try {
        if (-not ('RfpyNativeMethods' -as [type])) {
            Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class RfpyNativeMethods {
    [DllImport("user32.dll", SetLastError=true, CharSet=CharSet.Auto)]
    public static extern IntPtr SendMessageTimeout(
        IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam,
        uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);
}
'@
        }
        $result = [UIntPtr]::Zero
        [void][RfpyNativeMethods]::SendMessageTimeout(
            [IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, 'Environment',
            0x0002, 2000, [ref]$result
        )
    } catch { }
}


function Remove-RfpyStaleLaunchers {
    foreach ($dir in @($BinDir, (Join-Path $AppVenv 'Scripts'))) {
        foreach ($name in @('rfpy.exe','rfpy-script.py','rfpy.bat','rfpy.com','rfpy')) {
            $p = Join-Path $dir $name
            if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Remove-RfpyStaleUserPathEntries {
    $current = [Environment]::GetEnvironmentVariable('Path','User')
    if ([string]::IsNullOrWhiteSpace($current)) { return }
    $stale = @((Join-Path $AppVenv 'Scripts')) | ForEach-Object { $_.TrimEnd('\') }
    $parts = @($current -split ';' | Where-Object {
        $v = $_.Trim()
        if (-not $v) { return $false }
        return -not ($stale -contains $v.TrimEnd('\'))
    })
    [Environment]::SetEnvironmentVariable('Path', ($parts -join ';'), 'User')
}


function Remove-RfpyOldProfileShims {
    $docs = [Environment]::GetFolderPath('MyDocuments')
    if ([string]::IsNullOrWhiteSpace($docs)) { return }
    $begin = '# >>> RFPY COMMAND >>>'
    $end   = '# <<< RFPY COMMAND <<<'
    $pattern = '(?ms)^\\s*' + [regex]::Escape($begin) + '.*?' + [regex]::Escape($end) + '\\s*'
    foreach ($p in @((Join-Path $docs 'PowerShell\\profile.ps1'),(Join-Path $docs 'WindowsPowerShell\\profile.ps1')) | Select-Object -Unique) {
        if (-not (Test-Path -LiteralPath $p)) { continue }
        try {
            $content = Get-Content -LiteralPath $p -Raw
            $updated = [regex]::Replace($content,$pattern,'')
            if ($updated -ne $content) { [IO.File]::WriteAllText($p,$updated.TrimStart("`r","`n"),[Text.UTF8Encoding]::new($false)) }
        } catch { }
    }
}

function Expand-EmbeddedFile([string]$Base64,[string]$Destination) {
    Ensure-Folder (Split-Path -Parent $Destination)
    [IO.File]::WriteAllBytes($Destination, [Convert]::FromBase64String($Base64))
}

$AppBase64 = ''
$PsBase64 = ''
$CmdBase64 = ''
$ConfigBase64 = ''
$NoticeBase64 = ''
$LicenseBase64 = ''
$AuthorsBase64 = 'UkZQWSBhdXRob3JzCj09PT09PT09PT09PQoKT2xpdmllciBSRU5BVUxUIOKAlCBvcmlnaW5hbCBhdXRob3IgYW5kIHByb2plY3QgY3JlYXRvcgo='
$UvPsBase64 = ''
$UvCmdBase64 = ''

$started = [Diagnostics.Stopwatch]::StartNew()
Write-Host ('='*60)
Write-Host " RFPY installer v$InstallerVersion" -ForegroundColor Cyan
Write-Host ('='*60)
Write-Host "Installation      : $InstallDir"
Write-Host "uv                : $UvVersion"
Write-Host "Python manager    : $ToolPythonVersion"
Write-Host "Proxy initial     : $(if ($ProxyUrl) {$ProxyUrl} else {'desactive'})"

Write-Stage 'Preparation des repertoires'
foreach ($p in @($InstallDir,$BinDir,$AppDir,$ToolsDir,$UvDir,$RuntimeDir,$ConfigDir,$TempDir,(Join-Path $InstallDir 'stacks'),(Join-Path $InstallDir 'reports'))) { Ensure-Folder $p }
$probe = Join-Path $InstallDir ('.write-' + [guid]::NewGuid().ToString('N'))
Set-Content -LiteralPath $probe -Value ok -Encoding Ascii
Remove-Item -LiteralPath $probe -Force
Write-Success 'Racine accessible en ecriture'

Write-Stage "Bootstrap uv $UvVersion"
$needUv = $true
if (Test-Path -LiteralPath $UvExe) {
    try {
        $v = (Run-External -FilePath $UvExe -Arguments @('--version') -Capture).Output -join ' '
        if ($v -match [regex]::Escape($UvVersion)) { $needUv = $false; Write-Success "uv deja present : $v" }
    } catch { }
}
if ($needUv) {
    $arch = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { 'aarch64' } else { 'x86_64' }
    $download = if ($UvUrl) { $UvUrl } else { "https://github.com/astral-sh/uv/releases/download/$UvVersion/uv-$arch-pc-windows-msvc.zip" }
    $zip = Join-Path $TempDir 'uv.zip'
    $extract = Join-Path $TempDir 'uv-extract'
    Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $extract -Recurse -Force -ErrorAction SilentlyContinue
    Write-Host "[...] Telechargement : $download" -ForegroundColor DarkGray
    $iw = @{ Uri=$download; OutFile=$zip; UseBasicParsing=$true }
    if ($ProxyUrl) { $iw.Proxy = $ProxyUrl }
    Invoke-WebRequest @iw
    Expand-Archive -LiteralPath $zip -DestinationPath $extract -Force
    $found = Get-ChildItem -LiteralPath $extract -Recurse -Filter uv.exe | Select-Object -First 1
    if ($null -eq $found) { throw 'uv.exe absent de l archive telechargee.' }
    Copy-Item -LiteralPath $found.FullName -Destination $UvExe -Force
    $sig = Get-AuthenticodeSignature -FilePath $UvExe
    if ($sig.Status -eq 'Valid') { Write-Success 'Signature Authenticode uv valide' } else { Write-Host "[WARN] Signature uv : $($sig.Status)" -ForegroundColor Yellow }
}
Run-External -FilePath $UvExe -Arguments @('--version') | Out-Null

if ($ProxyUrl) {
    $env:HTTP_PROXY=$ProxyUrl; $env:HTTPS_PROXY=$ProxyUrl; $env:http_proxy=$ProxyUrl; $env:https_proxy=$ProxyUrl
}

Write-Stage "Installation du runtime RFPY Python $ToolPythonVersion"
Run-External -FilePath $UvExe -Arguments @('python','install',$ToolPythonVersion,'--install-dir',$RuntimeDir,'--no-bin') | Out-Null
$RuntimePython = Get-ChildItem -LiteralPath $RuntimeDir -Directory | Where-Object { $_.Name -like "cpython-$ToolPythonVersion-*" } | ForEach-Object { Join-Path $_.FullName 'python.exe' } | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
if (-not $RuntimePython) { throw "Python $ToolPythonVersion introuvable sous $RuntimeDir" }
Write-Success "Runtime : $RuntimePython"

Write-Stage 'Creation / mise a jour du runtime applicatif'
if (-not (Test-Path -LiteralPath $AppPython)) { Run-External -FilePath $UvExe -Arguments @('venv',$AppVenv,'--python',$RuntimePython) | Out-Null }
Run-External -FilePath $UvExe -Arguments @('pip','install','--python',$AppPython,'packaging') | Out-Null

Write-Stage 'Installation des fichiers RFPY'
Remove-RfpyStaleLaunchers
Remove-RfpyStaleUserPathEntries
Remove-RfpyOldProfileShims
Expand-EmbeddedFile -Base64 $AppBase64 -Destination (Join-Path $AppDir 'rfpy.py')
$rfpyPsPath = Join-Path $BinDir 'rfpy.ps1'
$rfpyCmdPath = Join-Path $BinDir 'rfpy.cmd'
Expand-EmbeddedFile -Base64 $PsBase64 -Destination $rfpyPsPath
Expand-EmbeddedFile -Base64 $CmdBase64 -Destination $rfpyCmdPath
$escapedRootPs = $InstallDir.Replace("'", "''")

# IMPORTANT : rfpy.ps1 contient des traductions FR/EN/DE/ES/ZH.
# Ne jamais le relire avec Get-Content sans encodage sous Windows PowerShell 5.1 /
# PS2EXE : le UTF-8 serait interprété avec la page de codes ANSI puis réécrit
# sous forme de mojibake. Lire explicitement en UTF-8 et écrire avec BOM pour
# rester compatible PowerShell 5.1 et PowerShell 7.
$utf8NoBom = [Text.UTF8Encoding]::new($false)
$utf8Bom   = [Text.UTF8Encoding]::new($true)
$psContent = [IO.File]::ReadAllText($rfpyPsPath, $utf8NoBom)
$psContent = $psContent.Replace("'__RFPY_ROOT__'", "'$escapedRootPs'")
[IO.File]::WriteAllText($rfpyPsPath, $psContent, $utf8Bom)

# rfpy.cmd reste volontairement ASCII.
$cmdContent = [IO.File]::ReadAllText($rfpyCmdPath, [Text.ASCIIEncoding]::new()).Replace('__RFPY_ROOT__', $InstallDir)
[IO.File]::WriteAllText($rfpyCmdPath, $cmdContent, [Text.ASCIIEncoding]::new())
Expand-EmbeddedFile -Base64 $UvPsBase64 -Destination (Join-Path $BinDir 'uv.ps1')
Expand-EmbeddedFile -Base64 $UvCmdBase64 -Destination (Join-Path $BinDir 'uv.cmd')
Expand-EmbeddedFile -Base64 $NoticeBase64 -Destination (Join-Path $InstallDir 'NOTICE')
Expand-EmbeddedFile -Base64 $LicenseBase64 -Destination (Join-Path $InstallDir 'LICENSE')
Expand-EmbeddedFile -Base64 $AuthorsBase64 -Destination (Join-Path $InstallDir 'AUTHORS')
if (-not (Test-Path -LiteralPath $ConfigFile)) {
    Expand-EmbeddedFile -Base64 $ConfigBase64 -Destination $ConfigFile
    if ($ProxyUrl) {
        $cfg = Get-Content -LiteralPath $ConfigFile -Raw | ConvertFrom-Json
        $cfg.proxy.enabled = $true
        $cfg.proxy.url = $ProxyUrl
        $cfg | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $ConfigFile -Encoding UTF8
    }
    Write-Success "Configuration initiale : $ConfigFile"
} else { Write-Success "Configuration conservee : $ConfigFile" }

if (-not $NoPath) {
    Ensure-UserPath $BinDir
    Signal-EnvironmentUpdate
}
$env:RFPY_HOME = $InstallDir

Write-Stage 'Verification de la commande RFPY'
if (-not $NoPath) {
    $storedPath = [Environment]::GetEnvironmentVariable('Path','User')
    $pathOk = @($storedPath -split ';' | Where-Object {
        -not [string]::IsNullOrWhiteSpace($_) -and $_.TrimEnd('\\') -ieq $BinDir.TrimEnd('\\')
    }).Count -gt 0
    if (-not $pathOk) { throw "$BinDir n est pas present dans le PATH utilisateur." }
    if (-not (Test-Path -LiteralPath (Join-Path $BinDir 'rfpy.ps1'))) { throw 'rfpy.ps1 absent apres installation.' }
    if (-not (Test-Path -LiteralPath (Join-Path $BinDir 'rfpy.cmd'))) { throw 'rfpy.cmd absent apres installation.' }
    $installedPsPath = Join-Path $BinDir 'rfpy.ps1'
    $installedBytes = [IO.File]::ReadAllBytes($installedPsPath)
    if ($installedBytes.Length -lt 3 -or $installedBytes[0] -ne 0xEF -or $installedBytes[1] -ne 0xBB -or $installedBytes[2] -ne 0xBF) {
        throw 'rfpy.ps1 n est pas encode en UTF-8 BOM.'
    }
    $installedPs = [IO.File]::ReadAllText($installedPsPath, [Text.UTF8Encoding]::new($true))
    if ($installedPs -match '__RFPY_ROOT__') { throw 'rfpy.ps1 contient encore un root non resolu.' }
    if ($installedPs -notmatch '正在打开 Web 控制台') {
        throw 'Verification UTF-8 de rfpy.ps1 echouee (traductions ZH corrompues).'
    }
    Write-Success 'Commande rfpy installee de facon persistante.'
    Write-Success 'Encodage CLI multilingue : UTF-8 BOM valide.' 
}

Write-Stage 'Doctor'
& $AppPython (Join-Path $AppDir 'rfpy.py') doctor
$doctorRc = $LASTEXITCODE
if ($doctorRc -gt 1) { Write-Host '[WARN] Doctor signale des points a verifier.' -ForegroundColor Yellow }

$started.Stop()
Write-Host ''
Write-Host ('='*60)
Write-Host ' RFPY INSTALLE' -ForegroundColor Green
Write-Host ('='*60)
Write-Host "Commande           : rfpy"
Write-Host "Menu               : rfpy -m"
Write-Host "Web                : rfpy web"
Write-Host "Doctor             : rfpy doctor"
Write-Host "Projet             : rfpy project add C:\dev\MONPROJET --python 3.14"
Write-Host "Env partage        : rfpy install RF-TOOLS --type shared --python 3.14 --profile robot"
Write-Host "Activer env        : rfpy activate MONENV"
Write-Host "Duree              : $($started.Elapsed.ToString('hh\:mm\:ss'))"
Write-Host ''
Write-Host 'La commande rfpy est enregistree dans le PATH utilisateur.' -ForegroundColor DarkGray
Write-Host ('Pont shell : ' + (Join-Path $BinDir 'rfpy.ps1') + ' + rfpy.cmd') -ForegroundColor DarkGray
Write-Host 'IMPORTANT : l EXE ne peut pas modifier le PowerShell parent deja ouvert.' -ForegroundColor Yellow
Write-Host ("Dans CE PowerShell, utiliser une fois : & '{0}'" -f (Join-Path $BinDir 'rfpy.ps1')) -ForegroundColor Cyan
Write-Host 'Dans une nouvelle console, utiliser simplement : rfpy' -ForegroundColor DarkGray

if ($LaunchWeb) { & $AppPython (Join-Path $AppDir 'rfpy.py') web }
